const CAREERS=RAW.map((r,i)=>({id:r[0],name:r[1],sector:r[2],mechanic:r[3],steps:r[4],icons:r[5],color:PALETTES[i%PALETTES.length],unlock:1,index:i}));
const state=JSON.parse(localStorage.getItem('game-v4')||'null')||{money:120000,xp:0,level:1,day:1,minute:450,nextNpc:1000,played:{},missions:0};
const save=()=>localStorage.setItem('game-v4',JSON.stringify(state));
let active=null,run=null,cityStarted=false,pan={x:0,y:0,z:1},drag=null,currentGroup='Tất cả';
function svgIcon(type,color='#fff'){const common=`viewBox="0 0 64 64" aria-hidden="true"`;const s={cup:`<svg ${common}><path fill="${color}" d="M15 14h34l-4 40H19z"/><path fill="#fff8" d="M20 20h24l-2 8H22z"/><circle cx="27" cy="43" r="4" fill="#25314c"/><circle cx="38" cy="47" r="4" fill="#25314c"/></svg>`,box:`<svg ${common}><path fill="${color}" d="M10 17 32 7l22 10v31L32 58 10 48z"/><path fill="#fff7" d="m10 17 22 11 22-11v9L32 37 10 26z"/></svg>`,screen:`<svg ${common}><rect x="8" y="10" width="48" height="35" rx="7" fill="${color}"/><rect x="14" y="16" width="36" height="23" rx="3" fill="#26324d"/><path d="M25 54h14M32 45v9" stroke="${color}" stroke-width="5" stroke-linecap="round"/></svg>`,heart:`<svg ${common}><path fill="${color}" d="M32 55S7 42 7 22C7 8 25 5 32 17 39 5 57 8 57 22c0 20-25 33-25 33Z"/></svg>`,leaf:`<svg ${common}><path fill="${color}" d="M53 9C30 9 12 19 11 39c-1 12 9 18 19 13 16-8 21-27 23-43Z"/><path d="M13 54c9-15 20-24 35-35" stroke="#fff" stroke-width="4" stroke-linecap="round"/></svg>`,camera:`<svg ${common}><path fill="${color}" d="M9 19h11l5-7h14l5 7h11v34H9z"/><circle cx="32" cy="36" r="11" fill="#26324d"/><circle cx="32" cy="36" r="6" fill="#8ee8ff"/></svg>`,ticket:`<svg ${common}><path fill="${color}" d="M8 17h48v12c-7 0-7 10 0 10v12H8V39c7 0 7-10 0-10z"/><path d="M32 18v32" stroke="#fff8" stroke-width="3" stroke-dasharray="5 5"/></svg>`,tool:`<svg ${common}><path fill="${color}" d="m14 48 28-28c-2-8 5-15 13-12l-8 8 2 7 7 2 8-8c3 8-4 15-12 13L24 58c-6 6-16-4-10-10Z"/></svg>`,book:`<svg ${common}><path fill="${color}" d="M8 12c10-4 18-2 24 4v39c-6-6-14-8-24-4zm48 0c-10-4-18-2-24 4v39c6-6 14-8 24-4z"/><path d="M32 16v39" stroke="#fff8" stroke-width="3"/></svg>`,bag:`<svg ${common}><path fill="${color}" d="M10 22h44l-4 34H14z"/><path d="M22 24c0-16 20-16 20 0" fill="none" stroke="${color}" stroke-width="6"/></svg>`,bottle:`<svg ${common}><path fill="${color}" d="M25 7h14v9l6 7v32H19V23l6-7z"/><path fill="#fff7" d="M22 31h20v12H22z"/></svg>`,brush:`<svg ${common}><path fill="${color}" d="M28 24h8v34h-8z"/><path fill="#ffb0c8" d="M20 6h24l-4 20H24z"/></svg>`,food:`<svg ${common}><circle cx="32" cy="32" r="25" fill="${color}"/><path fill="#fff8" d="M18 29h28c0 12-6 19-14 19s-14-7-14-19Z"/><circle cx="25" cy="25" r="4" fill="#6ebf72"/><circle cx="38" cy="23" r="5" fill="#ef826d"/></svg>`,spark:`<svg ${common}><path fill="${color}" d="m32 3 7 21 22 8-22 8-7 21-7-21-22-8 22-8z"/></svg>`};return s[type]||s.spark}
function npc(seed,role='citizen'){let x=seed>>>0;const rnd=()=>((x=(x*1664525+1013904223)>>>0)/4294967296);const skins=['#f3c8a8','#dca67d','#b97956','#8d5d45','#f0b98f'],hairs=['#25233a','#51362f','#7a4c31','#2d2b28','#9d6741'],shirts=['#637ef5','#f06e83','#58b88a','#e2a34c','#9d75df','#4aaac8'],pants=['#29364f','#48556f','#6c5366','#344b45'];return{id:seed,skin:skins[Math.floor(rnd()*skins.length)],hair:hairs[Math.floor(rnd()*hairs.length)],shirt:shirts[Math.floor(rnd()*shirts.length)],pants:pants[Math.floor(rnd()*pants.length)],speed:.55+rnd()*.8,role,name:['An','Bình','Chi','Duy','Giang','Hà','Khánh','Linh','Minh','Nam','Phúc','Quỳnh','Trang','Vy'][Math.floor(rnd()*14)]}}
function personEl(n,cls=''){const e=document.createElement('div');e.className=`person ${cls}`;e.dataset.npc=n.id;e.style.cssText=`--skin:${n.skin};--hair:${n.hair};--shirt:${n.shirt};--pants:${n.pants}`;e.innerHTML='<i class="shadow"></i><i class="leg l"></i><i class="leg r"></i><i class="arm l"></i><i class="arm r"></i><i class="body"></i><i class="head"></i><i class="hair"></i><i class="eye l"></i><i class="eye r"></i><i class="mouth"></i>';return e}
function updateHUD(){state.level=Math.max(1,Math.floor(state.xp/500)+1);$('#money').textContent=fmt(state.money)+'đ';$('#level').textContent=state.level;$('#xpFill').style.width=((state.xp%500)/5)+'%';$('#day').textContent='NGÀY '+state.day;const h=Math.floor(state.minute/60)%24,m=state.minute%60;$('#clock').textContent=String(h).padStart(2,'0')+':'+String(m).padStart(2,'0');const mini=$('#miniAvatar');if(!mini.children.length){const p=personEl(npc(777));p.style.transform='scale(.5)';p.style.left='-5px';p.style.top='0';mini.appendChild(p)}}
function toast(t){const el=$('#toast');el.textContent=t;el.classList.remove('hidden');requestAnimationFrame(()=>el.classList.add('show'));clearTimeout(el._t);el._t=setTimeout(()=>{el.classList.remove('show');setTimeout(()=>el.classList.add('hidden'),250)},1800)}
function makeLandingPeople(){const box=$('#landingPeople');[[76,72,.9],[83,78,1.05],[69,80,.75],[91,70,.82]].forEach((p,i)=>{const e=personEl(npc(80+i),'walk');e.style.left=p[0]+'%';e.style.top=p[1]+'%';e.style.transform=`scale(${p[2]})`;box.appendChild(e)})}
const GROUPS=[
{name:'Tất cả',sectors:[]},
{name:'Ăn uống',sectors:['Ăn uống']},
{name:'Mua sắm & Làm đẹp',sectors:['Bán lẻ','Làm đẹp']},
{name:'Sáng tạo',sectors:['Sáng tạo']},
{name:'Vận chuyển',sectors:['Vận chuyển','Vận hành']},
{name:'Kỹ thuật & Công nghệ',sectors:['Kỹ thuật','Công nghệ']},
{name:'Nông nghiệp & Thú cưng',sectors:['Nông nghiệp','Thú cưng']},
{name:'Giáo dục',sectors:['Giáo dục']},
{name:'Kinh doanh',sectors:['Kinh doanh']},
{name:'Du lịch & Dịch vụ',sectors:['Du lịch','Dịch vụ']},
{name:'Giải trí & Sự kiện',sectors:['Giải trí']},
{name:'Cộng đồng',sectors:['Cộng đồng']}
];
const FEATURED_IDS=['tra-sua','spa','logistics','gamedev','hotel','community-kitchen'];
function cardIllustration(c,seed){
 const wrap=document.createElement('div');wrap.className='career-art';wrap.style.setProperty('--c',c.color);
 wrap.innerHTML=`<div class="art-wall"><i></i><i></i></div><div class="art-counter"></div><div class="art-object one">${svgIcon(c.icons[0],'#fff')}</div><div class="art-object two">${svgIcon(c.icons[1],'#fff')}</div>`;
 const p=personEl(npc(seed),'work');p.classList.add('card-character');wrap.appendChild(p);return wrap;
}
function careerCard(c,featured=false){
 const b=document.createElement('button');b.className='catalog-card'+(featured?' featured-card':'');b.dataset.id=c.id;b.style.setProperty('--c',c.color);
 b.innerHTML=`<div class="card-art-slot"></div><div class="card-info"><small>${c.sector}</small><h4>${c.name}</h4><p>${c.steps.slice(0,3).join(' · ')}</p><span>CHƠI NGAY <b>→</b></span></div>`;
 b.querySelector('.card-art-slot').appendChild(cardIllustration(c,2100+c.index));b.onclick=()=>openCareer(c);return b;
}
function buildHub(){
 const featured=$('#featuredCareers');featured.innerHTML='';FEATURED_IDS.map(id=>CAREERS.find(c=>c.id===id)).filter(Boolean).slice(0,3).forEach(c=>featured.appendChild(careerCard(c,true)));
 const bar=$('#categoryBar');bar.innerHTML='';GROUPS.forEach((g,i)=>{const n=g.sectors.length?CAREERS.filter(c=>g.sectors.includes(c.sector)).length:CAREERS.length;const b=document.createElement('button');b.className=i===0?'active':'';b.dataset.group=g.name;b.innerHTML=`<b>${g.name}</b><span>${n}</span>`;b.onclick=()=>{currentGroup=g.name;$$('.category-bar button').forEach(x=>x.classList.toggle('active',x===b));renderCatalog()};bar.appendChild(b)});
 renderCatalog();spawnHubNPCs();
}
function renderCatalog(){
 const q=($('#careerSearch')?.value||'').trim().toLocaleLowerCase('vi');const g=GROUPS.find(x=>x.name===currentGroup)||GROUPS[0];
 let list=CAREERS.filter(c=>(!g.sectors.length||g.sectors.includes(c.sector))&&(!q||`${c.name} ${c.sector} ${c.steps.join(' ')}`.toLocaleLowerCase('vi').includes(q)));
 $('#visibleCount').textContent=list.length;const box=$('#careerCatalog');box.innerHTML='';
 const sectorOrder=['Ăn uống','Bán lẻ','Làm đẹp','Sáng tạo','Vận chuyển','Kỹ thuật','Nông nghiệp','Thú cưng','Dịch vụ','Giáo dục','Công nghệ','Kinh doanh','Du lịch','Vận hành','Giải trí','Cộng đồng'];
 const sectors=sectorOrder.filter(sec=>list.some(c=>c.sector===sec));
 sectors.forEach(sec=>{const section=document.createElement('section');section.className='career-section';const items=list.filter(c=>c.sector===sec);section.innerHTML=`<div class="sector-heading"><div><small>LĨNH VỰC</small><h4>${sec}</h4></div><span>${items.length} game</span></div><div class="career-row"></div>`;const row=section.querySelector('.career-row');items.forEach(c=>row.appendChild(careerCard(c)));box.appendChild(section)});
 if(!list.length)box.innerHTML='<div class="empty-search"><b>Không tìm thấy nghề này.</b><span>Thử tên nghề hoặc lĩnh vực khác.</span></div>';
}
function spawnHubNPCs(){const layer=$('#cityPeople');layer.innerHTML='';const cap=innerWidth<700?4:8;for(let i=0;i<cap;i++){const n=npc(state.nextNpc++),e=personEl(n,'walk');e.style.left=(4+i*(92/Math.max(1,cap-1)))+'%';e.style.bottom=(2+(i%3)*2)+'%';e.style.transform=`scale(${.58+(i%2)*.08})`;layer.appendChild(e)}save()}
function showJobs(){currentGroup='Tất cả';$$('.category-bar button').forEach((x,i)=>x.classList.toggle('active',i===0));$('#careerSearch').value='';renderCatalog();$('.game-library').scrollTo({top:$('.library-body').offsetTop-80,behavior:'smooth'})}
function showMissions(){const sheet=$('#citySheet');sheet.innerHTML=`<div class="sheet-head"><div><small>HÔM NAY</small><h2>Nhiệm vụ hôm nay</h2></div><button data-close>×</button></div><div class="job-grid"><div class="job-card"><small>NHIỆM VỤ</small><b>Hoàn thành 3 ca làm</b><span>${state.missions%3}/3 · thưởng 75.000đ</span></div><div class="job-card"><small>KHÁM PHÁ</small><b>Thử một nghề mới</b><span>Mỗi nghề có thao tác riêng</span></div><div class="job-card"><small>GAME</small><b>Gặp NPC mới</b><span>NPC được sinh procedural, không có trần tổng số</span></div></div>`;$('[data-close]',sheet).onclick=()=>sheet.classList.add('hidden');sheet.classList.remove('hidden')}
function showPhone(){const sheet=$('#citySheet');sheet.innerHTML=`<div class="sheet-head"><div><small>ĐIỆN THOẠI</small><h2>Tin nhắn</h2></div><button data-close>×</button></div><div class="job-grid"><div class="job-card"><small>NGƯỜI LẠ</small><b>“Quán mới mở hả? Nhìn xịn đó!”</b><span>2 phút trước</span></div><div class="job-card"><small>GAME</small><b>Hãy thử một nghề bạn chưa chơi hôm nay.</b><span>Thông báo hệ thống</span></div><div class="job-card"><small>KHÁCH QUEN</small><b>“Mai tui quay lại nha.”</b><span>NPC #${state.nextNpc-3}</span></div></div>`;$('[data-close]',sheet).onclick=()=>sheet.classList.add('hidden');sheet.classList.remove('hidden');$('#phoneDot').style.display='none'}
function openCareer(c){active=c;$('#city').classList.add('hidden');$('#career').classList.remove('hidden');document.documentElement.style.setProperty('--accent',c.color);document.documentElement.style.setProperty('--room',mix(c.color,'#dcecff',.72));$('#careerTitle').textContent=c.name;$('#careerSector').textContent=c.sector.toUpperCase();$('#careerBadge').innerHTML=svgIcon(c.icons[0],'#fff');$('#wallDecor').textContent=c.name.toUpperCase();$('#shiftTime').textContent='01:30';$('#shiftEarn').textContent='0đ';$('#combo').textContent='x1';$('#taskText').textContent='Quan sát nơi làm việc rồi bắt đầu ca';$('#taskProgress').style.width='0';$('#startShift').classList.remove('hidden');$('#orderBubble').classList.add('hidden');$('#careerResult').classList.add('hidden');renderRoom(c);spawnRoomPeople(c)}
function mix(a,b,t){const p=s=>[1,3,5].map(i=>parseInt(s.slice(i,i+2),16));const A=p(a),B=p(b);return '#'+A.map((v,i)=>Math.round(v*(1-t)+B[i]*t).toString(16).padStart(2,'0')).join('')}
function renderRoom(c){const props=$('#roomProps');const layouts=[['8%','27%','8%','24%'],['61%','27%','9%','23%'],['10%','24%','68%','26%'],['58%','25%','12%','25%']];const l=layouts[c.index%layouts.length];const sectorProps={
'Ăn uống':['food','cup'],'Bán lẻ':['bag','box'],'Làm đẹp':['brush','bottle'],'Sáng tạo':['camera','screen'],'Vận chuyển':['box','screen'],'Kỹ thuật':['tool','screen'],'Nông nghiệp':['leaf','box'],'Thú cưng':['heart','food'],'Dịch vụ':['book','bottle'],'Giáo dục':['book','screen'],'Công nghệ':['screen','tool'],'Kinh doanh':['book','screen'],'Du lịch':['ticket','bag'],'Vận hành':['ticket','screen'],'Giải trí':['spark','ticket'],'Cộng đồng':['heart','book']};const deco=sectorProps[c.sector]||['spark','box'];const workObjects=c.icons.map((ic,i)=>`<div class="prop decor-object" style="left:${18+i*16}%;top:${28+(i%2)*8}%"><span class="object-icon ${ic}"></span><small>${c.steps[i]}</small></div>`).join('');props.innerHTML=`<div class="prop counter" style="left:${l[0]};bottom:${l[1]};width:28%;--accent:${c.color}"></div><div class="prop shelf" style="right:${l[2]};top:${l[3]};width:150px;height:150px"></div><div class="prop plant" style="right:${18+(c.index%4)*4}%;bottom:${24+(c.index%3)*2}%"></div><div class="prop signboard" style="left:${10+(c.index%5)*2}%;top:25%;--accent:${c.color}">${c.sector}</div><div class="prop sector-icon a">${svgIcon(deco[0],c.color)}</div><div class="prop sector-icon b">${svgIcon(deco[1],c.color)}</div>${workObjects}`;$('#workArea').innerHTML='';}
function spawnRoomPeople(c){const layer=$('#roomPeople');layer.innerHTML='';const player=personEl(npc(777),'work');player.style.left='19%';player.style.bottom='27%';player.style.transform='scale(1.15)';layer.appendChild(player);const line=document.createElement('div');line.className='customer-line';for(let i=0;i<3;i++){const p=personEl(npc(state.nextNpc+i));p.style.transform=`scale(${1-i*.07})`;line.appendChild(p)}layer.appendChild(line);state.nextNpc+=3;save()}
function startShift(){if(run)return;run={time:90,earn:0,combo:1,score:0,round:0,done:0,timer:null,anim:null};$('#startShift').classList.add('hidden');nextRound();run.timer=setInterval(()=>{run.time--;$('#shiftTime').textContent=`${String(Math.floor(run.time/60)).padStart(2,'0')}:${String(run.time%60).padStart(2,'0')}`;if(run.time<=0)finishShift()},1000)}
function nextRound(){if(!run)return;run.round++;$('#workArea').innerHTML='';$('#orderBubble').classList.remove('hidden');const methods={assemble:mechanicAssemble,serve:mechanicServe,timing:mechanicTiming,sort:mechanicSort,choice:mechanicChoice,match:mechanicMatch,pattern:mechanicPattern,rhythm:mechanicRhythm,route:mechanicRoute,diagnose:mechanicDiagnose,sequence:mechanicSequence,quiz:mechanicQuiz,memory:mechanicMemory,manage:mechanicManage};(methods[active.mechanic]||mechanicSequence)()}
function setOrder(title,sub=''){$('#orderBubble').innerHTML=`<small>${sub||'KHÁCH ĐANG CHỜ'}</small><b>${title}</b>`}
function stations(order,shuffle=false){const area=$('#workArea'),arr=shuffle?[...order].sort(()=>Math.random()-.5):order;arr.forEach((idx,k)=>{const b=document.createElement('button');b.className='station';b.dataset.i=idx;b.style.left=(18+k*(64/(Math.max(1,arr.length-1))))+'%';b.style.top=(45+(k%2)*10)+'%';b.innerHTML=`<span class="object-icon ${active.icons[idx]}"></span><b>${active.steps[idx]}</b>`;area.appendChild(b)});return $$('.station',area)}
function success(base=7000){if(!run)return;run.combo=Math.min(9,run.combo+1);const gain=Math.round(base*(1+(run.combo-1)*.12));run.earn+=gain;run.score+=10*run.combo;run.done++;$('#shiftEarn').textContent=fmt(run.earn)+'đ';$('#combo').textContent='x'+run.combo;$('#taskProgress').style.width=Math.min(100,(run.done%6)/6*100)+'%';const customer=$('.customer-line .person');if(customer){customer.classList.add('happy');setTimeout(()=>customer.classList.remove('happy'),900)};setTimeout(nextRound,450)}
function fail(){if(!run)return;run.combo=1;$('#combo').textContent='x1';const customer=$('.customer-line .person');if(customer){customer.classList.add('sad');setTimeout(()=>customer.classList.remove('sad'),700)};toast('Chưa đúng, thử lại!')}
function mechanicAssemble(){const target=[0,1,2,3],picked=[];setOrder(`Đơn mới: ${active.steps.join(' → ')}`);$('#taskText').textContent='Tự tay hoàn thành đúng quy trình';stations(target,true).forEach(b=>b.onclick=()=>{const i=+b.dataset.i;if(i!==target[picked.length]){b.classList.add('wrong');setTimeout(()=>b.classList.remove('wrong'),350);return fail()}picked.push(i);b.classList.add('done','correct');if(picked.length===4)success(8200)})}
function mechanicServe(){const target=Math.floor(Math.random()*4);setOrder(`Khách gọi: ${active.steps[target]}`);$('#taskText').textContent='Nhìn yêu cầu của khách và phục vụ đúng';stations([0,1,2,3],false).forEach(b=>b.onclick=()=>{if(+b.dataset.i===target){b.classList.add('correct');success(7600)}else{b.classList.add('wrong');setTimeout(()=>b.classList.remove('wrong'),350);fail()}})}
function mechanicTiming(){setOrder(active.steps[run.round%4],'CANH THỜI ĐIỂM');$('#taskText').textContent='Chạm khi kim nằm trong vùng xanh';const area=$('#workArea');area.innerHTML='<div class="meter"><i class="meter-zone"></i><i class="meter-needle"></i></div><button class="tap-button">CHẠM!</button>';let p=0,d=1;const needle=$('.meter-needle',area);const tick=()=>{p+=d*1.4;if(p>=98||p<=0)d*=-1;needle.style.left=p+'%';run.anim=requestAnimationFrame(tick)};tick();$('.tap-button',area).onclick=()=>{cancelAnimationFrame(run.anim);p>=42&&p<=58?success(9000):fail();if(!(p>=42&&p<=58))setTimeout(nextRound,500)}}
function mechanicSort(){setOrder('Phân loại 4 món vào đúng khu','KÉO & THẢ');$('#taskText').textContent='Kéo từng món vào đúng khu vực';const area=$('#workArea'),cats=[0,1,2];cats.forEach((i,k)=>{const z=document.createElement('div');z.className='sort-bin';z.dataset.bin=i;z.style.cssText=`--c:${mix(active.color,'#ffffff',.35)};left:${16+k*29}%;bottom:18%`;z.textContent=active.steps[i];area.appendChild(z)});let done=0;for(let i=0;i<5;i++){const cat=i%3,p=document.createElement('div');p.className='parcel';p.dataset.cat=cat;p.textContent=active.steps[cat];p.style.left=(16+i*14)+'%';p.style.top=(33+(i%2)*10)+'%';area.appendChild(p);makeDraggable(p,el=>{const r=el.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2;const z=$$('.sort-bin',area).find(x=>{const q=x.getBoundingClientRect();return cx>q.left&&cx<q.right&&cy>q.top&&cy<q.bottom});if(z&&z.dataset.bin===el.dataset.cat){el.remove();done++;if(done===5)success(9800)}else fail()})}}
function mechanicChoice(){const good=Math.floor(Math.random()*4);setOrder('Khách cần bạn tư vấn','ĐỌC TÌNH HUỐNG');$('#taskText').textContent='Chọn phương án phù hợp nhất';const area=$('#workArea');area.innerHTML=`<div class="choice-board">${active.steps.map((x,i)=>`<button data-i="${i}"><small>${i===good?'PHÙ HỢP NHẤT':'LỰA CHỌN'}</small><b>${x}</b></button>`).join('')}</div>`;$$('.choice-board button',area).forEach(b=>b.onclick=()=>+b.dataset.i===good?success(8500):fail())}
function mechanicMatch(){const target=Math.floor(Math.random()*4);setOrder(`Khách đang tìm: ${active.steps[target]}`,'TÌM ĐÚNG MÓN');$('#taskText').textContent='Chọn đúng sản phẩm khách cần';stations([0,1,2,3],true).forEach(b=>b.onclick=()=>+b.dataset.i===target?success(8300):fail())}
function mechanicPattern(){const seq=[0,1,2].sort(()=>Math.random()-.5),pick=[];setOrder(`Mẫu: ${seq.map(i=>active.steps[i]).join(' → ')}`,'LÀM THEO MẪU');$('#taskText').textContent='Thực hiện đúng thứ tự mẫu';stations([0,1,2],true).forEach(b=>b.onclick=()=>{const i=+b.dataset.i;if(i!==seq[pick.length])return fail();pick.push(i);b.classList.add('done');if(pick.length===3)success(9200)})}
function mechanicRhythm(){setOrder(active.steps[run.round%4],'GIỮ NHỊP');$('#taskText').textContent='Chạm khi vòng màu khớp vòng trắng';const area=$('#workArea');area.innerHTML='<div class="rhythm-ring"><i class="rhythm-pulse"></i><button class="rhythm-hit">CHẠM</button></div><div class="tiny-note">Perfect 3 lần liên tiếp</div>';let scale=2.1,hits=0;const pulse=$('.rhythm-pulse',area);const tick=()=>{scale-=.018;if(scale<.72)scale=2.1;pulse.style.transform=`scale(${scale})`;pulse.style.opacity=String(clamp(1.5-scale/1.5,.2,1));run.anim=requestAnimationFrame(tick)};tick();$('.rhythm-hit',area).onclick=()=>{if(scale>.92&&scale<1.12){hits++;scale=2.1;$('.tiny-note',area).textContent=`Perfect ${hits}/3`;if(hits>=3){cancelAnimationFrame(run.anim);success(10500)}}else{hits=0;$('.tiny-note',area).textContent='Trượt nhịp · làm lại';fail()}}}
function mechanicRoute(){const opts=[['Đường tắt',2],['Đại lộ',3],['Đường vòng',5],['Hẻm nhỏ',4]].sort(()=>Math.random()-.5),best=Math.min(...opts.map(x=>x[1]));setOrder(active.steps[run.round%4],'ĐIỀU PHỐI TUYẾN');$('#taskText').textContent='Chọn tuyến nhanh nhất theo tình hình';$('#workArea').innerHTML=`<div class="route-board"><h3>Bản đồ vừa cập nhật giao thông</h3><div class="route-options">${opts.map(o=>`<button data-t="${o[1]}">Đường: ${o[0]}<b>${o[1]} phút</b></button>`).join('')}</div></div>`;$$('.route-options button').forEach(b=>b.onclick=()=>+b.dataset.t===best?success(9000):fail())}
function mechanicDiagnose(){const target=Math.floor(Math.random()*4);setOrder(`Dấu hiệu cho thấy vấn đề ở: ${active.steps[target]}`,'CHẨN ĐOÁN');$('#taskText').textContent='Kiểm tra và chọn đúng khu vực cần xử lý';stations([0,1,2,3],true).forEach(b=>b.onclick=()=>+b.dataset.i===target?success(9300):fail())}
function mechanicSequence(){const pick=[];setOrder(active.steps.join(' → '),'QUY TRÌNH');$('#taskText').textContent='Hoàn thành quy trình đúng thứ tự';stations([0,1,2,3],true).forEach(b=>b.onclick=()=>{const i=+b.dataset.i;if(i!==pick.length)return fail();pick.push(i);b.classList.add('done');if(pick.length===4)success(9600)})}
function mechanicQuiz(){const a=2+Math.floor(Math.random()*8),b=2+Math.floor(Math.random()*8),ans=a+b,opts=[ans,ans+1,ans-1,ans+2].sort(()=>Math.random()-.5);setOrder(`${a} + ${b} = ?`,'PHẢN XẠ');$('#taskText').textContent='Chọn đáp án nhanh để giữ combo';$('#workArea').innerHTML=`<div class="choice-board">${opts.map(x=>`<button data-v="${x}"><small>ĐÁP ÁN</small><b>${x}</b></button>`).join('')}</div>`;$$('.choice-board button').forEach(b=>b.onclick=()=>+b.dataset.v===ans?success(7600):fail())}
function mechanicMemory(){const seq=Array.from({length:3+Math.min(2,Math.floor(run.round/4))},()=>Math.floor(Math.random()*4)),input=[];setOrder('Quan sát chuỗi sáng','GHI NHỚ');$('#taskText').textContent='Nhớ thứ tự rồi lặp lại';const bs=stations([0,1,2,3],false);bs.forEach(b=>b.disabled=true);let k=0;const flash=()=>{if(k>=seq.length){bs.forEach(b=>b.disabled=false);return}const b=bs.find(x=>+x.dataset.i===seq[k]);b.classList.add('correct');setTimeout(()=>b.classList.remove('correct'),260);k++;setTimeout(flash,430)};setTimeout(flash,450);bs.forEach(b=>b.onclick=()=>{input.push(+b.dataset.i);const pos=input.length-1;if(input[pos]!==seq[pos])return fail();if(input.length===seq.length)success(9200)})}
function mechanicManage(){const good=Math.floor(Math.random()*4);setOrder('Có 4 việc cùng tới một lúc','ĐIỀU PHỐI');$('#taskText').textContent='Ưu tiên việc quan trọng nhất';$('#workArea').innerHTML=`<div class="choice-board">${active.steps.map((x,i)=>`<button data-i="${i}"><small>${['GẤP','MỚI','ĐANG CHỜ','CÓ THỂ HOÃN'][(i+good)%4]}</small><b>${x}</b></button>`).join('')}</div>`;$$('.choice-board button').forEach(b=>b.onclick=()=>+b.dataset.i===good?success(10000):fail())}
function makeDraggable(el,onDrop){let ox=0,oy=0;const move=e=>{const p=e.touches?e.touches[0]:e;el.style.left=(p.clientX-ox)+'px';el.style.top=(p.clientY-oy)+'px'};const up=()=>{removeEventListener('pointermove',move);removeEventListener('pointerup',up);onDrop(el)};el.onpointerdown=e=>{const r=el.getBoundingClientRect();ox=e.clientX-r.left;oy=e.clientY-r.top;el.style.position='fixed';el.style.zIndex=60;addEventListener('pointermove',move);addEventListener('pointerup',up)}}
function finishShift(){if(!run)return;clearInterval(run.timer);cancelAnimationFrame(run.anim);const r={...run};run=null;state.money+=r.earn;state.xp+=Math.max(80,Math.round(r.score*1.6));state.missions++;state.played[active.id]=(state.played[active.id]||0)+1;if(state.missions%3===0){state.money+=75000;toast('Nhiệm vụ hoàn tất +75.000đ')}save();updateHUD();$('#careerResult').innerHTML=`<div class="result-card"><div class="result-burst"></div><small>CA LÀM HOÀN TẤT</small><h2>${active.name}</h2><p>Bạn đã trực tiếp xử lý ${r.done} lượt công việc. GAME đã lưu tiến trình của nghề này.</p><div class="result-grid"><div><small>THU NHẬP</small><b>+${fmt(r.earn)}đ</b></div><div><small>ĐIỂM</small><b>${r.score}</b></div><div><small>LEVEL</small><b>${state.level}</b></div></div><div class="result-actions"><button class="leave">VỀ GAME</button><button class="again">LÀM CA KHÁC</button></div></div>`;$('#careerResult').classList.remove('hidden');$('.leave').onclick=leaveCareer;$('.again').onclick=()=>{$('#careerResult').classList.add('hidden');$('#startShift').classList.remove('hidden');$('#shiftTime').textContent='01:30';$('#shiftEarn').textContent='0đ';$('#combo').textContent='x1';$('#workArea').innerHTML='';$('#orderBubble').classList.add('hidden')};cloudSave()}
function leaveCareer(){if(run){clearInterval(run.timer);cancelAnimationFrame(run.anim);run=null}$('#career').classList.add('hidden');$('#city').classList.remove('hidden');$('#careerResult').classList.add('hidden');updateHUD()}
async function cloudSave(){try{await fetch('/api/save',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({playerId:localStorage.getItem('vn-player')||(localStorage.setItem('vn-player',crypto.randomUUID()),localStorage.getItem('vn-player')),save:state})})}catch{}}
function initCityPan(){const world=$('#cityWorld'),build=$('#cityBuildings');world.onpointerdown=e=>{if(e.target.closest('button'))return;drag={x:e.clientX,y:e.clientY,px:pan.x,py:pan.y};world.setPointerCapture?.(e.pointerId)};world.onpointermove=e=>{if(!drag)return;pan.x=clamp(drag.px+e.clientX-drag.x,-520,520);pan.y=clamp(drag.py+e.clientY-drag.y,-220,220);applyPan()};world.onpointerup=()=>drag=null;world.onwheel=e=>{e.preventDefault();pan.z=clamp(pan.z+(e.deltaY<0?.08:-.08),.72,1.35);applyPan()};function applyPan(){build.style.setProperty('--panx',pan.x+'px');build.style.setProperty('--pany',pan.y+'px');build.style.setProperty('--zoom',pan.z)}}
$('#enterCity').onclick=()=>{$('#landing').classList.add('hidden');$('#city').classList.remove('hidden');if(!cityStarted){buildHub();cityStarted=true}updateHUD();toast('Chọn một nghề và chơi ngay')};$('#jobsBtn').onclick=showJobs;$('#missionsBtn').onclick=showMissions;$('#phoneBtn').onclick=showPhone;$('#backCity').onclick=leaveCareer;$('#startShift').onclick=startShift;$('#settingsBtn').onclick=()=>toast('GAME · 60 nghề · NPC procedural');$('#careerSearch').addEventListener('input',renderCatalog);$('#careerSearch').addEventListener('keydown',e=>{if(e.key==='Escape'){e.currentTarget.value='';renderCatalog()}});document.addEventListener('keydown',e=>{if(e.key==='/'&&!$('#city').classList.contains('hidden')&&document.activeElement!==$('#careerSearch')){e.preventDefault();$('#careerSearch').focus()}});setInterval(()=>{if(!$('#city').classList.contains('hidden')){state.minute+=3;if(state.minute>=1440){state.minute=0;state.day++}updateHUD();save()}},5000);setInterval(cloudSave,45000);makeLandingPeople();updateHUD();
